@@ -0,0 +1,48 @@
+package com.example.contact;
+
+import java.io.Serializable;
+import java.util.ArrayList;
+import java.util.List;
+
+import com.vaadin.flow.server.VaadinSession;
+
+/**
+ * Keeps the messages that have been sent, newest first.
+ * <p>
+ * The store lives in the {@link VaadinSession}, so the list outlives a single
+ * visit to the contact view: leaving the view and coming back still shows
+ * everything that has been sent.
+ */
+public class MessageStore implements Serializable {
+
+    private static final MessageStore DETACHED = new MessageStore();
+
+    private final List<Message> messages = new ArrayList<>();
+
+    /**
+     * The store of the current session, created on first use.
+     */
+    public static MessageStore current() {
+        VaadinSession session = VaadinSession.getCurrent();
+        if (session == null) {
+            return DETACHED;
+        }
+        MessageStore store = session.getAttribute(MessageStore.class);
+        if (store == null) {
+            store = new MessageStore();
+            session.setAttribute(MessageStore.class, store);
+        }
+        return store;
+    }
+
+    public synchronized void add(Message message) {
+        messages.add(0, message);
+    }
+
+    /**
+     * The messages sent so far, newest first.
+     */
+    public synchronized List<Message> messages() {
+        return new ArrayList<>(messages);
+    }
+}
