+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+/**
+ * The same behaviour, checked in a real browser. Not run by surefire; run it
+ * with {@code mvn -o test -Dtest=ContactViewIT -DfailIfNoTests=false}.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewIT extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    private TextFieldElement name() {
+        return TextFieldElement.getByLabel(page, "Name");
+    }
+
+    private EmailFieldElement email() {
+        return EmailFieldElement.getByLabel(page, "Email");
+    }
+
+    private TextFieldElement phone() {
+        return TextFieldElement.getByLabel(page, "Phone");
+    }
+
+    private TextAreaElement message() {
+        return TextAreaElement.getByLabel(page, "Message");
+    }
+
+    private ButtonElement send() {
+        return ButtonElement.getByText(page, "Send");
+    }
+
+    private void fill(String nameValue, String emailValue, String phoneValue,
+            String messageValue) {
+        name().setValue(nameValue);
+        email().setValue(emailValue);
+        phone().setValue(phoneValue);
+        message().setValue(messageValue);
+    }
+
+    @Test
+    void viewShowsHeadingLinkAndEnabledSend() {
+        assertEquals("Contact", page.locator("h1").textContent());
+        assertTrue(page.getByText("About").isVisible());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        send().assertEnabled();
+    }
+
+    @Test
+    void emptyFormReportsEveryFailingRule() {
+        send().click();
+
+        name().assertInvalid();
+        name().assertErrorMessage("Name is required");
+        email().assertInvalid();
+        email().assertErrorMessage("Give an e-mail address or a phone number");
+        message().assertInvalid();
+        message().assertErrorMessage("Message is required");
+
+        assertFalse(new NotificationElement(page).isOpen());
+        assertEquals(0, GridElement.get(page).getTotalRowCount());
+    }
+
+    @Test
+    void invalidEmailIsReported() {
+        fill("Ada", "not-an-email", "", "Hello there");
+        send().click();
+
+        email().assertInvalid();
+        email().assertErrorMessage("Enter a valid e-mail address");
+        assertEquals(0, GridElement.get(page).getTotalRowCount());
+        name().assertValue("Ada");
+        message().assertValue("Hello there");
+    }
+
+    @Test
+    void tooLongMessageIsReported() {
+        fill("Ada", "ada@example.com", "", "x".repeat(501));
+        send().click();
+
+        message().assertInvalid();
+        message().assertErrorMessage(
+                "Message must be at most 500 characters");
+        assertEquals(0, GridElement.get(page).getTotalRowCount());
+    }
+
+    @Test
+    void sendingShowsNotificationAndClearsTheForm() {
+        fill("Ada", "ada@example.com", "", "Hello there");
+        send().click();
+
+        NotificationElement notification = new NotificationElement(page);
+        notification.assertOpen();
+        assertTrue(notification.getText().contains("Message sent"));
+
+        GridElement grid = GridElement.get(page);
+        assertEquals(1, grid.getTotalRowCount());
+        assertEquals("Ada", grid.findCell(0, 0).orElseThrow()
+                .getCellContentLocator().textContent());
+        assertEquals("Hello there", grid.findCell(0, 1).orElseThrow()
+                .getCellContentLocator().textContent());
+
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+
+        send().assertDisabled();
+        name().setValue("Grace");
+        send().assertEnabled();
+    }
+
+    @Test
+    void phoneAloneIsEnoughAndEnterSends() {
+        fill("Ada", "", "+358 40 123 4567", "Hello there");
+        name().getInputLocator().press("Enter");
+
+        new NotificationElement(page).assertOpen();
+        assertEquals(1, GridElement.get(page).getTotalRowCount());
+    }
+
+    @Test
+    void emptyFormLeavesWithoutAskingAndWithoutReloading() {
+        page.evaluate("window.__notReloaded = true");
+
+        page.getByText("About").click();
+
+        page.waitForSelector("h1:text('About')");
+        assertEquals("About", page.locator("h1").textContent());
+        assertEquals(Boolean.TRUE, page.evaluate("window.__notReloaded"));
+        assertFalse(new DialogElement(page).isOpen());
+    }
+
+    @Test
+    void keepEditingStaysOnTheViewAndDiscardLeaves() {
+        fill("Ada", "", "", "Hello there");
+
+        page.getByText("About").click();
+
+        DialogElement dialog = new DialogElement(page);
+        dialog.assertOpen();
+
+        ButtonElement.getByText(page, "Keep editing").click();
+        dialog.assertClosed();
+        assertEquals("Contact", page.locator("h1").textContent());
+        name().assertValue("Ada");
+        message().assertValue("Hello there");
+
+        page.getByText("About").click();
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Discard").click();
+
+        page.waitForSelector("h1:text('About')");
+        assertEquals("About", page.locator("h1").textContent());
+    }
+
+    @Test
+    void messagesSurviveLeavingTheView() {
+        fill("Ada", "ada@example.com", "", "Hello there");
+        send().click();
+        new NotificationElement(page).assertOpen();
+
+        page.getByText("About").click();
+        page.waitForSelector("h1:text('About')");
+        page.getByRole(com.microsoft.playwright.options.AriaRole.LINK,
+                new com.microsoft.playwright.Page.GetByRoleOptions()
+                        .setName("Contact")).click();
+        page.waitForSelector("h1:text('Contact')");
+
+        assertEquals(1, GridElement.get(page).getTotalRowCount());
+        send().assertEnabled();
+    }
+}
