+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertFalse(name.isInvalid());
+        assertFalse(message.isInvalid());
+        assertFalse(find(Notification.class).exists());
+        assertEquals(0, test(grid).size());
+        // What the user typed stays in the form.
+        assertEquals("Ada", name.getValue());
+        assertEquals("not-an-email", email.getValue());
+        assertEquals("Hello there", message.getValue());
